:3px;font-size:9px;font-variant-numeric:tabular-nums;padding:0 2px;border-radius:3px;background:var(--journal-card);color:var(--journal-muted)}.pc-grid-help{margin:16px 0 0;text-align:center;color:var(--journal-muted);font-size:11px;line-height:1.6}.pc-details{padding:18px;border-left:1px solid var(--journal-border);background:var(--journal-card);min-width:0}.pc-selected-heading{display:flex;align-items:center;gap:7px}.pc-selected-heading>.pokemon-portrait{width:64px}.pc-selected-heading h3{margin:4px 0;font:500 22px Georgia,serif;overflow-wrap:anywhere;color:var(--journal-heading)}.pc-selected-heading>div{min-width:0}.pc-selected-heading>div>span{font-size:11px}.pc-types{display:flex;gap:5px;margin:10px 0}.pc-types span{border:1px solid var(--journal-border);border-radius:4px;padding:3px 8px;font-size:10px;color:var(--journal-accent);background:var(--journal-soft)}.pc-hp{font-size:11px;color:var(--journal-muted)}.pc-traits{font-size:11px;margin:15px 0}.pc-traits>div{display:flex;justify-content:space-between;gap:6px;padding:7px 0;border-bottom:1px solid var(--journal-border)}.pc-traits dt{color:var(--journal-muted)}.pc-traits dd{margin:0;text-align:right;overflow-wrap:anywhere}.pc-moves{font-size:11px;line-height:1.7;color:var(--journal-muted)}.pc-actions{display:grid;gap:9px;margin-top:18px}.pc-actions button{min-height:44px;padding:10px;border:1px solid var(--journal-border);border-radius:8px}.pc-actions .pc-primary{color:var(--journal-on-accent);background:var(--journal-accent);font-weight:600}.pc-actions small{color:var(--journal-muted);font-size:10px}.pc-swap-label{display:grid;gap:7px;font-size:11px;color:var(--journal-muted)}.pc-swap-label select{min-width:0;width:100%;min-height:44px;border:1px solid var(--journal-border);border-radius:6px;background:var(--journal-paper);padding:6px}.pc-actions .pc-release{margin-top:5px;color:var(--journal-danger);background:none;border-color:transparent}.pc-idle{padding:20px 0;color:var(--journal-muted);font-size:12px;line-height:1.7}.pc-idle svg{display:block;width:68px;margin:0 0 18px;color:var(--journal-accent)}.pc-idle h3{margin:0;font:500 22px Georgia,serif;color:var(--journal-heading)}.pc-idle small{display:block;margin-top:18px;font-size:10px}.pc-footer{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:12px 18px;border-top:1px solid var(--journal-border);color:var(--journal-muted);background:var(--journal-soft);font-size:10px}.pc-confirm-backdrop{position:absolute;inset:0;display:grid;place-items:center;padding:20px;background:var(--journal-backdrop);z-index:2}.pc-confirm{width:min(390px,100%);max-height:100%;overflow:auto;padding:22px;border:1px solid var(--journal-border);border-radius:16px;background:var(--journal-card);box-shadow:var(--journal-shadow);text-align:center}.pc-confirm>.pokemon-portrait{width:80px;margin:auto}.pc-confirm h3{font:500 24px Georgia,serif;color:var(--journal-heading);overflow-wrap:anywhere}.pc-confirm p{font-size:12px;color:var(--journal-muted);line-height:1.6}.pc-confirm>div{display:grid;gap:9px;margin-top:20px}.pc-confirm button{min-height:44px;padding:9px;border:1px solid var(--journal-border);border-radius:7px;background:var(--journal-soft)}.pc-confirm .pc-danger{color:var(--journal-danger);border-color:var(--journal-danger);background:var(--journal-paper);font-weight:600}.pc-terminal :is(button,select):focus-visible{outline:2px solid var(--journal-accent);outline-offset:2px}
